package org.example.reaction;

import java.util.Map;

// counts는 네 종류를 항상 모두 담는다(0 포함). myReaction은 비로그인이거나 공감하지 않았으면 null
public record ReactionSummaryResponse(
        Long postId,
        ReactionKind myReaction,
        Map<ReactionKind, Long> counts,
        long total
) {
}
